const LOVE_CARDS = {
  "1": { card: "А ♥", text: "Энергия дня. Туз Червей.\n\nВам предстоит день большой любовной активности. А♥ может показывать начало одного или многих важных отношений. Часто Червовый Туз показывает стремление к любви и привязанности, которое вырывает вас из жизненного благополучия.\n\nЭто очень сильное влияние, оно делает вас инициатором отношений. Может быть, вы были одиноки долгое время и сегодня кто-то важный появится в вашей жизни.\n\nВ любом случае эта сильная карта обычно означает образование одной или многих новых связей, по крайней мере, одна из которых будет очень важной." },
  "2": { card: "2 ♥", text: "Энергия дня. Двойка Червей.\n\nИмея карту влюбленных в таком выдающемся положении, можете быть уверены, различные взаимоотношения будут иметь наибольшее значение сегодня. Если вы одиноки, очень возможно, что у вас будут важные отношения.\n\nЧему научит вас сегодня Червовая Двойка? Так это тому, каковы ваши потребности в партнерстве, какой партнер больше подходит, и какое место занимаете в любви и романтических отношениях. Может случиться, что вы просто возвращаетесь на сцену свиданий и ищите того необычного человека, который завершит картину вашего счастливого дома и общественной жизни.\n\nКогда вы в браке, то же самое может оказаться верным, но скорее всего ближайшие друзья приобретут большое значение в вашей жизни, и вы выясните, каково ваше место в дружбе аналогичным образом. Любовь и чувства очень важны и составляют большую часть вашей жизни сейчас." },
  "3": { card: "3 ♥", text: "Энергия дня. Тройка Червей.\n\nЭто, скорее всего, будет день приобретения опыта в любви либо дружбе. Если вы ищете новых связей, сегодня предоставит вам широкий выбор. 3♥ часто появляется в раскладах тех, кто долгое время не имел связей, и как раз начинает новую. Если вы не заинтересованы в новых любовных связях, Червовая Тройка может означать встречу многих новых, интересных друзей сегодня, или нерешительность, долго царящую в вашей настоящей личной жизни.\n\n3♥ вносит элемент разнообразия в личностную жизнь или сферу взаимоотношений. Эта карта, в зависимости от влияний планет и положения дел в любви и дружбе, может быть и благоприятной, одновременно и неблагоприятной." },
  "4": { card: "4 ♥", text: "Энергия дня. Четверка Червей.\n\nКак одна из свадебных карт Червовая Четверка означает период, когда проблемы личной жизни решены, это также период удовлетворенности во всех отношениях и очень благоприятный для женитьбы. 4♥ также влияет на существующий брак или текущую связь. 4♥ – Карта семьи, скорее всего этот день будет полон удовлетворенности в эмоциональном, личном и семейном плане.\n\nЕсли вы уже женаты или находитесь в постоянной связи, семья занимает главную роль, независимо от обстоятельств, вы должны уделять ей больше внимания, чем обычно, по какой-либо причине.\n\nЕсли вы одиноки, и ваше сердце никому не принадлежит, тема знакомств приобретает особенно важное значение. Возможно, у вас сегодня будет начало удачного романа." },
  "5": { card: "5 ♥", text: "Энергия дня. Пятерка Червей.\n\nСегодня день сердечных изменений. Это можно трактовать, что вы расходитесь или разводитесь с кем-нибудь, это займет существенно много времени вашего, энергии и внимания.\n\nА может быть сегодня вы просто эмоционально неспокойны, и хотите освободиться от настоящих связей и исследовать новые. Это может включать путешествие, и это путешествие может разлучить вас с любимым или любимыми.\n\nВполне возможно произойдет кардинальное изменение в вашем подходе к взаимоотношениям, браку и дружбе. Сегодня день перехода от одного типа взаимоотношений к другому." },
  "6": { card: "6 ♥", text: "Энергия дня. Шестерка Червей.\n\nОсновными словами для этого дня для вас являются компромисс и уступки. С 6♥, кармической картой, вы можете рассчитывать на соглашения с окружающими, которые заставят вас сделать некоторые уступки для достижения мира и гармонии во взаимоотношениях.\n\nЭтот день станет днем достижений, если вы ищете новых связей или хотите изменить старые. Червовая Шестерка – хорошее влияние для сохранения существующих близких взаимоотношений. Возможен элемент «платы долгов привязанности».\n\nЕсли в этом дне вы вступите в новые серьезные отношения, это наверняка сбалансирует ваши кармические весы в связи с привязанностями и любовью." },
  "7": { card: "7 ♥", text: "Энергия дня. Семерка Червей.\n\nС 7♥ сегодня вы можете обнаружить себя вовлеченным в одну или несколько связей. Червовая Семерка означает, что этот день будет днем изменений в любви и чувствах в ваших взаимоотношениях с близкими. Будучи высоко духовным числом, семерка обещает успех в любви только в случае освобождения от зависимости, от мыслей о личных нуждах и большей самоотдачи. Может случиться, что ваши ближайшие друзья, члены семьи или любимые разочаруют вас сегодня.\n\nИзвлеките уроки из этого опыта. Вы почувствуете необходимость освободиться от мелких связей и расширить свои взгляды. Дайте своей духовной силе возможность вырасти и завоевать эту область, и вы обнаружите, что превратились в более счастливого и удовлетворенного человека.\n\nДля тех, кто занят духовной работой, эта карта означает большой прогресс и успех сегодня. Это может быть очень успешный день для самоотдачи, особенно в роли консультанта или личного помощника." },
  "8": { card: "8 ♥", text: "Энергия дня. Восьмерка Червей.\n\nЧервовая Восьмерка говорит, что сегодня имеется значительная духовная сила, которая принесет успех в различной деятельности, связанной с группами людей, такой как участие в спектаклях, выступления или торговля. Это также указатель развивающейся в вас духовной силы, которая может использована для улучшения жизни.\n\nВы проводите крайне много времени вне дома, встречаете новых интересных людей и разнообразным образом всегда находитесь центром внимания. Хорошее время для выдвижения новых идей, распространения своих взглядов.\n\nКогда вы используете власть для обретения успеха, будьте осторожны, постарайтесь не обидеть окружающих." },
  "9": { card: "9 ♥", text: "Энергия дня. Девятка Червей.\n\nКажется странным, что карта всеобщей любви может быть также одной из карт разрыва. Однако разрыв – это конец личных отношений и переход от личной к всеобщей любви.\n\nЭтот день, видимо, приготовил для вас одну или несколько важных эмоциональных травм. По меньшей мере, у вас произойдет охлаждение в отношениях с бывшим любовником или супругом. Но Червовая Девятка может также указывать на кончину в семье либо среди ваших друзей, животных. Одно или несколько ваших отношений закончится, и если вы загляните глубже в себя, вы можете обнаружить, что есть причины для конца, которые будут хороши как для вас, так и для другого.\n\nЭта карта часто означает разочарование, но только в случае, если мы пытаемся оттянуть конец. Если вы отдаетесь на волю высших сил, вы можете испытать повышенное состояние сознания, которое также представлено этой сильной картой. Включение в работу, которая дает любовь другим людям особенно к большим группам людей, – залог большого успеха сегодня. Вы жертвуете собой ради других." },
  "10": { card: "10 ♥", text: "Энергия дня. Десятка Червей.\n\n10♥ говорит нам, что сегодня придет успех, признание и популярность. Особенно благоприятна общественная деятельность или работа с большими группами людей.\n\nПризнание у них будет играть внушительную роль в вашей жизни, а какую именно – будет зависеть от других обстоятельств. Возможно, вы занимаетесь бизнесом, где вы хотите больше проявить себя и получить признание. Эта карта ясно указывает на то, что вас ждет большой успех в этих областях.\n\nЭто одна из лучших карт для исполнителей, причем Червовая Десятка указывает, что большие группы людей будут к вам хорошо относиться. В общем, это наилучшее возможное влияние. Эта карта может преодолеть отрицательные воздействия, которые имеют место, и вы даже можете стать известным." },
  "11": { card: "J ♥", text: "Энергия дня. Валет Червей.\n\nСегодня вы будете иметь мощное духовное влияние на свою жизнь со стороны карты в матрице судьбы Червовый Валет, который известен как карта Христа. Для вас это означает, что вы будете вынуждены чем-то пожертвовать, что каким-то образом поможет другим людям.\n\nЭто может быть связано с необходимостью отказаться от каких-то личных целей и честолюбивых замыслов или просто с необходимостью затратить ваше время и средства на помощь кому-то, менее удачливому, чем вы. Вы узнаете, что такое жертва сегодня – вот истинный смысл этой карты. Человек или люди, для кого вы принесли эту жертву, обычно моложе.\n\nЧервовый Валет обладает мощнейшей духовной энергией, в каком роде это проявится покажет день и урок в нем. Духовная энергия этой карты может принести также мистические откровения, чистые помыслы и чувства, так что надо все время следить за ее появлением и не терять внимания." },
  "12": { card: "Q ♥", text: "Энергия дня. Дама Червей.\n\nЕсли в этот день вы одиноки, велика вероятность, что в вашей голове постоянно сидит мысль о браке. Q♥ – одна из двух брачных карт.\n\nЕсли вы одинокая мать, Червовая Дама может указывать, что вы будете тратить больше времени и сил на ваших детей сегодня, либо сконцентрируетесь на мысли стать матерью. Однако если вы замужем, ваша семья и/или ваш супруг будут основным центром вашего внимания сегодня.\n\nЭто может иметь как положительные, так и отрицательные последствия. Все зависит от текущей ситуации. Помните о том, что эта карта может сделать ленивым вас." },
  "13": { card: "К ♥", text: "Энергия дня. Король Червей.\n\nК♥ правит благодаря любви. У него есть сила и понимание любви, и он знает, как их использовать. Эта мощная карта подарит вам свою силу сегодня, и вы сможете использовать ее в вашей личной и профессиональной жизни для достижения больших успехов.\n\nПомните только, что этой силой нельзя злоупотреблять. Правьте с помощью любви, и все будет великолепно. Если это карта человека, который возможно сыграет важную для вас роль сегодня, то это обычно пожилой мужчина, добросердечный с мягким характером, большим обаянием и эмоциональной убедительностью. Эта карта либо означает, что этот Червовый Король будет играть основную роль в жизни сегодня, либо что вы сами проявите эти качества.\n\nK♥ – это символ сильных чувств и мощного влияния на других, что может либо помочь вам достичь целей, либо доставить вам неприятности." },
  "14": { card: "А ♣", text: "Энергия дня. Туз Треф.\n\nА♣ символизирует рождение или начало идеи, способ общения, философию жизни или отрасли знания. Он также может символизировать сегодня ваши желания получить новую специфическую информацию, которой у вас сейчас нет. Это может проявиться как начало нового курса обучения, чтение новых книг, приобретение нового компьютера или программного обеспечения, как нового способа хранения информации.\n\nТрефовый Туз показывает, что сегодня родятся многие новые идеи и новая философия. Вы решили начать новый курс обучения или новый проект, который включает писательский труд, обмен информацией, публичные выступления или преподавание. Сегодня повышено ваше природное любопытство, что может привести вас ко многим новым идеям, концепциям, верованиям и способам общения." },
  "15": { card: "2 ♣", text: "Энергия дня. Двойка треф.\n\nСегодня ваше внимание сконцентрируется на том, как общаетесь с встречаемыми людьми. Скорее всего, вы окажетесь в ситуациях, в которых необходимо развивать гармонические отношения с окружающими.\n\nМожет быть, будет один особенный человек, с которым вы разделяете взгляды и мысли, и кто станет центральной фигурой для вас сегодня. В любом случае ваша способность делиться тем, что вы знаете, с окружающими, не вызывая их возражений, – это самое главное.\n\nС Трефовой Двойкой всегда возможны споры, которые покажут вам области, где вы можете развить качественные по содержанию отношения с людьми." },
  "16": { card: "3 ♣", text: "Энергия дня. Тройка Треф.\n\nСкорее всего, ваша голова будет забита мыслями сегодня. Трефовая Тройка активизирует ум, который пополняется новыми идеями и путями их осуществления. Это может заставить вас расшириться в разных векторах одновременно. К примеру, вы можете изучать два или больше предметов в одно и то же время. У вас множество хороших идей. Вы отыскать сможете уникальные и ценные пути осуществления проектов и взгляды на вещи.\n\nЕсли это творчество и многосторонность экстремальны, вы можете оказаться под влиянием более низких вибраций этой сильной карты – беспокойство и нерешительность. Большинство людей недостаточно приспособлены, чтобы выстоять, но все же некоторые это могут. Все ведь зависит от вас. Чтобы взять большее от этой карты, запишите все идеи, пришедшие сегодня. Возможно, не сможете осуществить их прямо сейчас, но они все равноценны, и могут быть сохранены на потом, когда способность к творчеству будет менее развита." },
  "17": { card: "4 ♣", text: "Энергия дня. Четверка Треф.\n\nЭто день умственной стабильности и общей удовлетворенности во всех делах. Независимо от ваших занятий и интересов вы обнаружите, что вы способны создать внутреннюю умиротворенность, которая позволяет делам идти наилучшим образом.\n\nЭто очень хорошее влияние Трефовой Четверки, так как именно ум обычно является источником наших проблем. Под этим влиянием особенно успешно проходит интеллектуальная деятельность, такая как писательская, преподавательская или обучение.\n\nЕдинственный негативный аспект появления этой карты – упрямство и умственный застой, недальновидность." },
  "18": { card: "5 ♣", text: "Энергия дня. Пятерка Треф.\n\nСегодня день важных для вас изменений, как в вашем сознании, так и вне его, а также и в окружающем мире. На глубоком уровне в вашей вере, философии или взглядах на будущее происходит значительный сдвиг.\n\nТакие изменения обусловлены новыми влияниями, появившимися в вашей жизни, или, возможно, тем, что узнаете во время путешествий. Часто эта карта появляется в раскладах тех людей, которые черпают новые идеи в школе или на новой работе.\n\nТакже часто она означает любопытство и беспокойство. Многие переселяются под влиянием Трефовой Пятерки, поэтому если вы размышляете о смене жительства, время действовать пришло. Хотя это влияние внешнее, оно отразится на вашем образе мышления. Негативными проявлениями этой карты может стать скептицизм по отношению к идеям окружающих и неприятие никаких философий или идеологий." },
  "19": { card: "6 ♣", text: "Энергия дня. Шестерка Треф.\n\nЕсли вы склонны к развитию ваших психических способностей, или если вы их используете в работе, этот день может принести прогресс. Ваши врожденные интуитивные способности повышаются, и на них сосредотачивается внимание.\n\nБолее того, это должен быть день относительной стабильности. В жизни царит гармония и мир. Чтобы достичь подобной гармонии, часто необходимо идти на компромисс. В этом дне компромиссы, скорее всего, относятся к идеям, или убеждениям, или путям общения.\n\nСегодня могут быть перечеркнуты планы путешествия или предполагавшиеся изменения." },
  "20": { card: "7 ♣", text: "Энергия дня. Семерка Треф.\n\nСегодня осознаете некоторые новые и действенные методы мышления, которые трансформируют жизнь к лучшему. Также вероятно, что вы поделитесь данными методами с окружающими.\n\nПонимание того, что от вашего образа мысли во многом зависит неудача либо успех в жизни, заставляет вас сознательно принять новые идей, мысли и убеждения. Возможно, вы будете читать новые книги либо примете участие в работе, что откроет науку позитивных утверждений перед вами. Постепенно вы постигаете эти утверждения, вам хочется делиться ими с окружающими, здесь сможете достичь определенного внутреннего успеха.\n\nПрактикуя позитивное мышление и разделяя его с окружающими, вы, возможно, выйдите на другой, новый уровень сознания и к вам придут многие озарения сегодня." },
  "21": { card: "8 ♣", text: "Энергия дня. Восьмерка Треф.\n\n8♣ вносит большую власть в жизнь сегодня – власть сознания. Будучи одной из 3х фиксированных карт она отдает еще большую силу для достижения целей и победы над трудностями, чем другие восьмерка. Трефовая Восьмерка сегодня обещает успех во всех сферах умственной деятельности.\n\n8♣ увеличивает мощь вашего сознания. Эта сила может принести вам успех во всех профессиях, руководимых Меркурием, таких как писательская деятельность, публичные выступления, образование или общение. Это также сила, которая поможет преодолеть большинство трудностей и препятствий к достижению целей, возникающих сегодня." },
  "22": { card: "9 ♣", text: "Энергия дня. Девятка Треф.\n\nТрефовая Девятка – это карта душевного разочарования, иногда связанного с окончанием чего-либо в вашей жизни. Сегодня вы переживете безусловное прекращение чего-либо.\n\nЭто может проявиться в виде утраты или завершения некоторого направления в работе, или в виде людей, препятствующих вашим планам до такой степени, что вы должны отказаться от них. Высшие силы подскажут вам сегодня, что пора оставить некоторую сокровенную идею или план и идти дальше. Если вы сможете почувствовать это и измениться, вы обнаружите, что покончив с этим, вам станет намного лучше.\n\nПоложительное действие этой карты заключается в том, что она может дать вам в качестве награды «универсальное знание» и успехи при совместном его использовании с другими людьми." },
  "23": { card: "10 ♣", text: "Энергия дня. Десятка Треф.\n\n10♣ может принести определенный успех и признание в одной из сфер умственной деятельности. Это может быть публикация работ или преподавание, либо другие области, где большие группы людей имеют возможность наслаждаться вашим блеском и талантом.\n\nПризнание ваших талантов и усилий – это знак этого дня, и это будет касаться тем или иным образом всех сторон вашей жизни и бросит отблеск незаурядности на ваши любовные отношения.\n\nОднако, если сегодня нет продуктивного и конструктивного выхода для вашего ума, Трефовая Десятка возможно укажет на проблемы стрессов и бессонницы. Найдите хороший выход для вашей умственной энергии. Это принесет вам успех и признание." },
  "24": { card: "J ♣", text: "Энергия дня. Валет Треф.\n\nСегодня мы будем иметь дело с проявлением творческой и бьющей через край энергией, либо в вас самих, либо у тех, кто интеллектуально стимулирует вас, возможно в каком-то молодом человеке.\n\nЭта творческая активность может быть с большой пользой и успехом направлена во множество областей, например, писательский труд, торговые дела или туда, где новые созидательные идеи очень важны. Сегодня действительно будет для вас днем творческой активности, и вы можете ожидать хороших результатов от всех видов творческой работы.\n\nОднако избегайте безответственности и легкомыслия под влиянием Трефового Валета и следите также за теми, кто может сыграть такую роль в вашей жизни." },
  "25": { card: "Q ♣", text: "Энергия дня. Дама Треф.\n\nСегодня вы достигнете определенного совершенства в одной из информационных областей. Вы также возможно обнаружите в себе сегодня способности к работе, связанной в любом смысле с информацией.\n\nПередача знаний или информации другим людям в Трефовой Даме, может иметь много разных форм. В вас будет очень сильна природная интуиция, и возможно, обнаружите, что в состоянии добраться к скрытой информации для своего успеха. Вы находитесь в королевском дворе знаний.\n\nИспользуйте это влияние для достижения успеха, совершенства." },
  "26": { card: "К ♣", text: "Энергия дня. Король Треф.\n\nТрефовый Король – это человек, обладающий большой властью благодаря приобретенному и усовершенствованному знанию. Сегодня у вас возможно будет много дел с таким человеком, либо вы проявите эти стороны своей личности, будучи королем; этот человек требует уважения от других и обычно добивается этого.\n\nЧасто такие люди оказываются во главе какого-то бизнеса или учреждения. В любом случае – люди, живущие своим умом и не терпящие вмешательства других. Сегодня вы сами возможно проявите некоторые либо все эти качества, которые с большим успехом могут использованы в вашей работе.\n\nОсобенно большой успех они могут принести, если работа связана с написанием книг, обменом информацией, издательской деятельностью или публичными выступлениями. Под этим влиянием любое интеллектуальное начинание ожидает успех." },
  "27": { card: "A ♦", text: "Энергия дня. Туз Бубен.\n\nБубновый Туз – сильная карта, означающая мощный импульс сегодня к приобретению собственности или денег. Это часто сообщает о начале нового бизнеса или финансового предприятия и всегда означает желание заработать деньги по любой причине.\n\nЗачем- то вы решили, что именно сегодня надо серьезнее отнестись к финансовому положению и сделать что-либо в этой области. Это желание может положить начало новому финансовому предприятию.\n\nОстерегайтесь, чтобы желание подобного плана не завладело вами целиком, смотрите по сторонам, это так важно сегодня." },
  "28": { card: "2 ♦", text: "Энергия дня. Двойка Бубен.\n\nСегодня вы сконцентрируетесь на сотрудничестве с откровенно деловыми людьми для достижения собственных финансовых целей. Вам необходима поддержка и участие для того, чтобы достичь указанных деловых целей.\n\nПо данной причине, скорее всего, много будет встреч и общения с другими. Иногда Бубновая Двойка может означать страх делать дела одному. Вам необходим кто-то еще, чтобы поделить риск, также как и награду.\n\nЭто может дать ошеломительный результат, если вы сотрудничаете с состоятельными и удачливыми людьми. День важных дел и встреч, вклады, бизнес партнерство." },
  "29": { card: "3 ♦", text: "Энергия дня. Тройка бубен.\n\nСегодня вы стоите на своего рода развилке ценностей. Хотите ли этого либо хотите того? Как относитесь к деньгам и любви? Что самое главное? Подобные вопросы, скорее всего, займут главное место в вашем сознании сегодня, в котором новые пути в работе, любви и финансах приведут к удовлетворению.\n\nКогда мы позволяем себе испытывать альтернативные чувства, мы часто теряем внимание, и это может привести к уменьшению финансового успеха. Мы растрачиваем наши силы и посвящаем меньше времени конкретному проекту или начинанию. В таком случае помните, что очень важно пройти через это и не беспокойтесь по поводу отсутствия успеха.\n\nВам необходимо выразить свое творчество и экспериментировать сегодня. Позже вы решите, какой путь больше подходит для вашего дальнейшего удовлетворения." },
  "30": { card: "4 ♦", text: "Энергия дня. Четверка Бубен.\n\nНезависимо от вашего настоящего финансового положения, вы наверняка почувствуете, что пришло время удовлетворенности и благоприятного финансового положения. Бубновая Четверка желанная карта, особенно когда дела шли не так хорошо в последнее время.\n\nВам становятся ясны ценности, и вы хорошо понимаете, что в жизни наиболее важно. По крайней мере, сегодня вы точно знаете, какое место занимают деньги среди других важных вещей в вашей жизни.\n\nЭто знание ведет к достатку и улучшению благосостояния, так как все в жизни стоит на своих местах. У вас достаточно денег, чтобы решить свои проблемы." },
  "31": { card: "5 ♦", text: "Энергия дня. Пятерка Бубен.\n\nПеред вами важный день изменений, которые приведут вас на новое совершенно место. Кардинальное изменение в том, что имеет важное значение, скорее всего, вызовет изменения в работе, отношении к финансам либо даже в отношениях с людьми.\n\nПод этим сильным влиянием вы даже можете переехать к новому месту. Так как наша жизнь устроена так, чтобы давать то, что мы считаем наиболее необходимым, вместе со сменой внутренней картины этих вещей, вам не остается ничего, как последовать за влиянием масти. Чтобы наиболее благоприятным образом провести день под Бубновой Пятеркой, дайте изменениям войти в жизнь, не задумывайтесь, что за этим стоит.\n\nКогда вы изменяетесь, оторвитесь от прошлого, не думайте о предстоящем будущем, оно не всегда ясно." },
  "32": { card: "6 ♦", text: "Энергия дня. Шестерка Бубен.\n\nБубновая Шестерка приводит к постоянству. Это хорошо, если находитесь в устойчивом финансовом положении в этот день, но могут быть определенные трудности, когда ощущаете недостаток в финансах. Шесть – это кармическое число. Оно означает силу ценностей и неприятие перемен. Сегодня вас постоянно осаждают бьющие по карману неоплаченные счета, вы пытаетесь вырваться и можете оказаться в материальной яме.\n\nС иной стороны, когда распознаете присущий этой карте потенциал, вы можете улучшить положение, сделав упор, что вам платят во всех делах, связанных с бизнесом, финансами. Это наверняка принесет вам дополнительную отдачу, особенно под кармической денежной картой. Что посеешь, то и пожнешь." },
  "33": { card: "7 ♦", text: "Энергия дня. Семерка Бубен.\n\nСегодня вы получите ценные уроки, касающиеся денег и их роли в жизни. В ходе разных событий и ситуаций вам откроется ваше отношение к деньгам и уровень внутреннего благосостояния.\n\nЧувствуете ли себя процветающим или обнищавшим, Бубновая Семерка покажет вам ваше внутреннее состояние по этому поводу, и вы увидите, насколько связаны внутренние процессы и окружающая вас реальность. Если сегодня перед вами встанут определенные финансовые проблемы, спросите себя, чувствуете ли вы себя свободно, или испытываете страх перед ними. Это влияние обещает большой финансовый успех, если приняли установку на процветание и благодарность.\n\nВозможно, вы испытаете сильное чувство сопричастности, поддержки всего мира под этим благоприятным духовным влиянием." },
  "34": { card: "8 ♦", text: "Энергия дня. Восьмерка Бубен.\n\n8♦ говорит вам о том, что сегодня вы приобретете значительную финансовую власть. В вашей власти заработать много денег, и вы обнаружите, что у вас их больше, чем обычно. Эта карта также представляет встречи с финансовыми целями.\n\nВозможно, в этом дне у вас есть определенные цели, относящиеся к тому, чего вы хотите достичь. Бубновая Восьмерка обещает, что у вас найдутся необходимые средства, когда это понадобится. Будьте осторожны в ваших финансовых делах, не обижайте окружающих и не заставляйте их действовать по вашему все время.\n\nХотя в ваших силах заставить их делать это, вы можете вызвать у окружающих негативное отношение, которое когда-нибудь отразится на вас." },
  "35": { card: "9 ♦", text: "Энергия дня. Девятка Бубен.\n\nСегодня вероятны для вас крупные финансовые расходы или повторяющиеся разочарования, связанные с вашим денежным положением.\n\nВаше отношение к этим финансовым затратам напрямую повлияет на их результаты. Бубновая Девятка – это карта, говорящая о необходимости часто платить деньги в том либо ином виде и, по-видимому, этот день этим и запомнится. Если сегодня вы займете универсальную позицию «будь, что будет», вы обнаружите заботу высших сил о вас, не надо ничего бояться. Филантропия обязательно принесет успех и признание." },
  "36": { card: "10 ♦", text: "Энергия дня. Десятка Бубен.\n\nСегодня вы будете много думать о деньгах. Вероятно это большая сумма денег. Однако эта карта не гарантирует, что вы действительно заработаете или получите большую сумму денег.\n\nВы можете быть вовлечены в дела, где фигурирует большая сумма, но вовсе не обязательно ваша. Это может относиться к имуществу, вашей работе, разводу или к каким-то другим вещам.\n\nВ некоторых случаях Бубновая Десятка указывает на большие деньги, которые можно получить. Это не конкретно, но совершенно точно, что вы будете много думать о большой сумме денег." },
  "37": { card: "J ♦", text: "Энергия дня. Валет Бубен.\n\nJ♦ – карта торговца, молодого, зарабатывающего деньги человека, у которого всегда полно новых идей и способов, как делать деньги. Это незаурядное интуитивное влияние, которое подарит вам сегодня много хороших идей, когда бы и где бы эта карта ни появилась в вашем раскладе.\n\nСегодня у вас будет возможность развить и использовать ваши большие творческие способности в финансовых делах. Это очень хорошая карта для людей, занимающихся торговлей.\n\nОпять же в Бубновом Валете есть что-то незрелое и хитрое. Сдержите ваши обещания и будьте честными во всех ваших делах." },
  "38": { card: "Q ♦", text: "Энергия дня. Дама Бубен.\n\nQ♦ представляет женщину, которая часто живет не по средствам. Она часто успешно занимается личным бизнесом или имеет способности к бизнесу. Ее девиз – не жалеть денег, и она щедра к любимым.\n\nВозможно, в вашей жизни есть такая женщина (или мужчина) и тогда сегодня Q♦ будет в центре вашего внимания. Однако, вы сами будете иметь (может быть) некоторые черты Бубновой Дамы, упомянутые выше. Влияние Q♦ может быть очень благоприятным в сфере управления бизнесом и принести успех финансов в любом бизнесе либо других начинаниях.\n\nОднако, помните о расточительности Q♦, которая сопровождается ее деловой сообразительностью." },
  "39": { card: "K ♦", text: "Энергия дня. Король Бубен.\n\nСегодня вы, скорее всего, будете иметь успех в вашем бизнесе и в финансовых предприятиях. Бубновый Король оказывает большую поддержку в сфере бизнеса и финансов и практически гарантирует, что вы примете много правильных решений. Бизнес в центре внимания.\n\nСледите, чтобы деньги не стали единственной целью в вашей жизни, так как вследствие этого могут пострадать другие сферы, например взаимоотношения с близкими.\n\nУ карты есть так же негативная сторона – трудности с теми же финансами и властью. Будьте внимательны и работайте над собой." },
  "40": { card: "A ♠", text: "Энергия дня. Туз Пик.\n\nСегодня происходят превращения самых различных видов, но это всегда мощное фундаментальное изменение в отношении к какой-либо жизненной сферы. Сегодня подскажет вам, какого рода это преобразование. Скорее всего, это будет день больших перемен для вас. В течение него к вам может прийти первый опыт интимных отношений, смерть или второе рождение. Возможно даже кто-то, кого вы знаете, уйдет из жизни. Если так случится, это будет, скорее всего, кто-то близкий вам, и вы еще сильнее почувствуете, что вы смертны.\n\nСегодня могут произойти также радикальные изменения в вашей работе. Вы можете встать на совершенно новую стезю, оставив в прошлом законченную главу вашей жизни. Эта перемена может быть неприятным, но конечный результат сделает вас бодрее и жизнерадостнее. Главную роль в этом дне может сыграть вовлечение вас в секретную работу или работу, которая затронет ваши личные тайны.\n\nПиковый Туз – это карта, которая представляет науку о Картах, Орден Магии и другие тайные организации, которые помогают человеку понять глубокие мистерии жизни, так что вы можете обнаружить в себе увлечение подобного рода сегодня." },
  "41": { card: "2 ♠", text: "Энергия дня. Двойка Пик.\n\nНеважно, работали ли вы один или нет, этот день приведет вас в непосредственный контакт с другими, необходимый для достижения ваших личных целей и честолюбивых планов. Сегодня рассматривайте партнерство на многих уровнях, особенно в работе. Сотрудничество часто требует компромисса, а иногда и жертвы, особенно если конечный результат очень важен.\n\nВ вашем случае, я уверен, игра стоит свеч. Под Пиковой Двойкой вы получите важные уроки о сотрудничестве. Сотрудничество может включать новых людей и расширяться вширь для достижения успеха." },
  "42": { card: "3 ♠", text: "Энергия дня. Тройка Пик.\n\nСегодня ваши внутренние силы разделятся на два пути: или вы на двух работах работаете сразу, имея дело с физическим стрессом, или у вас возникнут старые проблемы со здоровьем. Но зависит от того, как вы используете энергию сильной Пиковой Тройки. Вы стоите на своего рода, перекрестке вашей жизни. Возможно, вы будете стараться сыграть слишком много ролей одновременно. Вы чувствуете настоятельное желание творить и исследовать одновременно множество путей. При удачном стечении обстоятельств вы можете стать более продуктивным, чем когда-либо. Секрет – держать энергию на высоком уровне и твердо помнить, что вы делаете два или более дел сразу. Не ожидайте, что вы встанете на одну тропу, плывите с энергией этой сильной Пиковой Тройки и расслабляйтесь время от времени.\n\nИногда вещи, который происходят «в пиках» – это вещи, которых не сможем избежать, хотя возможно вас ждет успех в этом. Просто заботьтесь о собственном здоровье и поймите, что проблемы в этой области являются, скорее всего, результатом глубокого конфликта или разлада внутри вас. Разрешите конфликт, и вы решите проблему. Карта разногласий, опасайтесь физических стрессов, трансформируйте разногласие в дополнение противоположностей." },
  "43": { card: "4 ♠", text: "Энергия дня. Четверка Пик.\n\nСегодня вам нужно проявить гибкость. Тогда Пиковая Четверка может принести урегулирование разнообразных проблем, получить ответы на ряд вопросов. Пиковая Четверка представляет постоянство и сбалансированность внутреннего огня, которое дает силы для выполнения задач и приводит к хорошему здоровью.\n\nЕдинственным отрицательным проявлением этой карты может стать необходимость тяжелой работы и крайнее упрямство.\n\nЭта карта предопределяет удовлетворение практически во всех вопросах здоровья и работы. Под этим мощным влиянием у вас есть силы, чтобы преодолеть любые сложности, будь то в здоровье или в работе. Куда бы не направили свою энергию, вы достигнете успеха в этой области." },
  "44": { card: "5 ♠", text: "Энергия дня. Пятерка Пик.\n\nСегодня вам предстоят многие фундаментальные изменения. Эти изменения, скорее всего, будут сопровождаться внутренним беспокойством. Для вас пришло время двигаться в новых направлениях.\n\nЭти новые направления могут быть новыми полями деятельности или изменением места жительства. У вас может появиться сильное желание, путешествовать, которое вовлечет вас в интересное приключение.\n\nОчень возможны изменения в здоровье, особенно если вы немолоды. Есть надежда, что эти изменения к лучшему. Сегодня может случиться долгое путешествие или переезд." },
  "45": { card: "6 ♠", text: "Энергия дня. Шестерка Пик.\n\nТрудности в здоровье, которые вы сегодня преодолеваете, это результат этих вредных привычек. На бытовом уровне Пиковая Шестерка означает время, когда здоровье и работа неизменны, то есть она может предотвращать изменения.\n\nТак эта карта становится картой безработицы. 6♠ в любом периоде может означать время, когда новая работа не находится, так что лучше всего добиться желаемого положения на работе перед тем, как 6♠ появляется в вашем раскладе. 6♠ может предотвратить или отсрочить путешествие или планы смены работы или переезда на новое место.\n\nЭто день приобретения опыта на самых разных уровнях. Все под влиянием сильной 6♠ . Скорее всего сегодня будет меньше возможностей для путешествий" },
  "46": { card: "7 ♠", text: "Энергия дня. Семерка Пик.\n\nОзначает, что этот день может принести трудности в работе или здоровье или успех в духовной деятельности. Он может стать днем, когда вам придется вдвойне испытать плохое отношение, накопившееся ранее.\n\nСчитайте, что это карта духовных изменений. Пришло время собрать вместе свои мысли, слова и дела и посмотреть, как они влияют на мир вокруг вас. Тогда можно понять возможности духовного успеха под Пиковой Семеркой. Возможности внутреннего развития в этом дне огромны.\n\nВсе возникающие под этим влиянием проблемы могут быть решены внутри вас. Рассматривайте самого себя как источник успеха и поднимайтесь ступень за ступенью к желаемой работе и состоянию здоровья." },
  "47": { card: "8 ♠", text: "Энергия дня. Восьмерка Пик.\n\n8♠ говорит нам, что сегодня мы обретем больше власти и контроля над своим здоровьем и работой и вообще власти. Сила эта может использоваться для достижения более высокого положения на работе, улучшения здоровья или успеха в любой области жизни.\n\nВласть и успех, приносимые Пиковой Восьмеркой, должны быть правильно применены и направлены на достижение наибольшего успеха. Когда вы неправильно используете эту власть, докучаете окружающим, навязываете им свои желания, вы создадите плохую карму, которая приведет к проблемам будущего.\n\nОпределите собственные цели и используйте власть мудро. В руках у вас палочка волшебная." },
  "48": { card: "9 ♠", text: "Энергия дня. Девятка Пик.\n\nСегодня Пиковая девятка указывает на болезнь, проблемы с работой и мучительные «завершения» в вашей жизни. Это может проявляться как завершение работы или проекта, или все время возникающая проблема со здоровьем, что говорит о необходимости совершенно нового подхода к своему здоровью и питанию.\n\n9♠ может указывать также на духовную работу и большой успех для вас в этой области сегодня. Использование универсальных принципов – вот ключ к успеху. Это может означать расставание без сожаления с тем, что проходит, и расширение своих жизненных целей, включая сюда гуманитарную деятельность, что поможет вам реализовать положительный потенциал сильной Пиковой Девятки. Пиковая девятка – Карта смерти, одновременно является магическим числом Вселенной. В какой путь двигаться – решать вам, и матрица судьбы поможет." },
  "49": { card: "10 ♠", text: "Энергия дня. Десятка Пик.\n\nЭто будет для вас день успехов, достижений задуманных целей и мечтаний. 10♠ – наилучшая карта успеха и удовлетворения от работы и здоровья.\n\nХотите ли вы иметь отличное здоровье или большее признание в работе, эта карта даст вам силы и решимость воплотить мечты в реальность. Используйте преимущества этой карты и сделайте этот день одним из лучших в вашей жизни.\n\nСила карты может использована с успехом в любой сфере жизни сегодня. Пиковая Десятка – как раз то, что нужно для осуществления всех желаний." },
  "50": { card: "J ♠", text: "Энергия дня. Валет Пик.\n\nПиковый Валет обычно указывает на трудолюбивого молодого человека, возможно также склонного к недобросовестности и нелегальной деятельности, за которым нужен глаз да глаз. В духовном плане это карта рассматривается как «посвящение» в высшую мудрость.\n\nВы вероятно обнаружите, что имеете дело с одним либо несколькими людьми, которые играют закулисную роль сегодня, или обнаружите, что вас обвинили в нечестности. Советую вам быть внимательными во всех сегодняшних делах и перестать доверять кому-либо, не проверив предварительно, что за личность. Не оставляйте также ваши ценности без присмотра и держите двери на замке.\n\nВо всех вариантах, возможно, сегодня вы посвящены в несколько новых духовных учений и верований. Вы можете даже начать жить по иным принципам, связанным с новым духовным путем, на который вступили." },
  "51": { card: "Q ♠", text: "Энергия дня. Дама Пик.\n\nQ♠ – это много работающий человек, часто менеджер, работающий в должности, связанной с обслуживанием или обеспечением бизнеса либо какого-то учреждения.\n\nВ этом смысле, если сегодня в вашем раскладе появилась Q♠, она подарит вам свой потенциал проницательности и деловых организационных способностей. Это можно успешно использовать в любой области. глубинном уровне – Пиковая Дама власть над собой.\n\nКуда бы они ни попала, эта карта даст вам опыт власти над той стороной жизни, которая определяется периодом, на который она выпала. Власть над собой означает успех во внешней сфере, который придет благодаря самоконтролю и знанию самого себя." },
  "52": { card: "K ♠", text: "Энергия дня. Король Пик.\n\nЭтот день может быть переломным для вас во многих отношениях. Сила Пикового Короля может с успехом использована по существу в разнообразных сферах жизни. Выбор за вами. Использование знаний и правильный подход принесут желаемые результаты сегодня. У К♠ нет нужды хвастать своими достижениями. Он властитель и знает об этом.\n\nПоэтому под Пиковым Королем необходимо расти профессионально, развивать творческий потенциал, развивать интуицию, уметь отвечать на вопросы, заданные Вселенной, Судьбой и перестать бежать от заданных задач.\n\nЭто Король Королей, который объединяет власть остальных трех королей плюс власть над душой." },
};// ================================================================
