const SUIT_TEXTS = {"Бубны": "Бубны олицетворяют деньги. Люди, родившиеся под этой мастью, пришли в этот мир (все по-разному) научиться правильно относиться к деньгам, к материальным ценностям. Бубны — масть финансов и ценностей, — зрелость и период карьерных достижений, осень. Элемент — Земля, масть Пентаклей в Таро.\nМасть Бубен символизирует восприимчивость, практичность, деньги и способность к оценке. У высокоразвитых представителей масти эти способности выходят за пределы материальной сферы, распространяясь на духовные ценности и личные качества. В характеристике менее развитого человека Бубны указывают на финансовые интересы.\nБубны тесно связаны с ценностями в самом широком смысле слова и постоянно стремятся выяснить, что в этой жизни достойно внимания, а что — нет. Все на свете для них имеет свою цену, и до некоторой степени они ассоциируют себя со своими ценностями и имуществом. Бубны еще в детстве вырабатывают методы, благодаря которым добиваются желаемого. Их жизненная философия основана на том, что человек пойдет на все, чтобы получить награду или избежать наказания.\nНаходясь в плохом настроении, представитель Бубновой масти обычно идет за покупками, чем как бы компенсирует нанесенные обиды. Однако, Бубны склонны к слишком неразумным и обильным тратам. Кроме того, им следует помнить о качестве приобретаемых вещей. Если они покупают что-нибудь некачественное, то этим наносят себе гораздо больший вред, чем представители любой другой масти. С другой стороны, стремление к качеству подразумевает и более значительные расходы, и это может превратиться в замкнутый круг, заставляющий Бубну постоянно нервничать из-за нехватки денег.\nПредставители масти Бубен — лучшие на свете торговцы; они обладают исключительной способностью убеждать других людей в ценности того или иного предмета. Значительную часть рекламы, с которой мы сталкиваемся, создают представители Бубновой масти. Среди продавцов также много Бубен или людей с большим количеством бубновых карт в Жизненном Наборе. Поверив в ценность и качество того или иного товара, Бубна пойдет на все, чтобы его разрекламировать.\nБольшинство людей, относящихся к Бубновой масти, объективно оценивают свои материальные возможности, что служит залогом успеха. Это качество помогает Бубнам превратить свои или чужие способности и таланты в реальные деньги. Что еще важнее, — оно наделяет их устойчивой внутренней системой понимания жизни. Бубны, четко сознающие свои ценности, никогда не попадут под влияние чужой истины, философии или под воздействие эмоциональных факторов. Каждый новый опыт и новая информация оценивается Бубнами на предмет извлечения практической пользы. На первый взгляд может показаться, что такая оценочная система используется только для заработка или обретения материальной стабильности, но, в конечном итоге, эти качества помогают Бубнам понять, что же делает их счастливыми.\nВсе Бубны рано или поздно делают главной целью своей жизни добывание денег и имущества. Благодаря этому, они получают возможность лучше понять самих себя. Заработав желанную «кучу денег», они обнаруживают, насколько эта цель была бессмысленной, и осознают, что счастье не сводится к богатству. Но даже усвоив этот урок, Бубны по-прежнему любят деньги и обожают тратить их.", "Пики": "Люди-пики зачастую сильные духом. Именно их можно назвать самыми духовно развитыми людьми во всей «колоде». И их, нужно заметить, не так уж и много. Пики — масть труда, здоровья и духовности, — преклонные годы, зима. Элемент — Огонь, масть Жезлов в Таро.\nМасть Пик символизирует потребность воплощения идей в реальность. Высокоразвитые люди, представленные этой мастью, предприимчивы, организованны и готовы идти на жертвы ради всеобщего блага. Пики действуют и живут иначе, чем остальные карты. Они способны не поддаваться на манипуляции Червей, Треф и Бубен, благодаря своей силе воли. Менее развитые личности масти Пики чаще погружаются в суету повседневности, постоянно совершая одни и те же ошибки.\nПики — это труженики, озабоченные качеством своего труда, что зачастую интересует их больше, чем доход, который он приносит. Руководитель, родившийся под влиянием масти Пик, может проявлять исключительную суровость и безжалостность к подчиненным, рассчитывая, что они будут вкладывать в работу столько же сил, сколько он сам.\nПики олицетворяют мудрость и опыт, у них более зрелый взгляд на жизнь, чем у большинства других людей. Они не терпят, когда кто-то пытается их контролировать, поэтому стремятся взять под контроль как можно большую часть окружающей действительности. Это сильные люди, обладающие несгибаемой волей, поэтому многие представители этой масти вынуждены решать проблемы лидерства и в личных отношениях. Они борются с партнером за власть и контроль до тех пор, пока не разрешат свой внутренний конфликт в этой области.\nОднако, удержаться на достигнутой вершине Пики могут лишь в том случае, если хорошо освоили качества, связанные с тремя другими мастями. Если представитель Пик не развивает у себя какой-либо аспект другой масти, он становится жертвой проблем в той области, которая соответствует этой масти. К примеру, Пики часто сталкиваются с большими трудностями в личных отношениях. Это связано с удаленностью Пик от червовой масти и приводит к тому, что жизненные области, связанные с Червами, им в определенной степени чужды. Многие Пики считают, что хорошая работа и выполнение долга важнее, чем отношения и эмоциональная сфера. Это, конечно, не означает, что Пики не способны вступить в счастливый брак, просто большинство представителей этой масти испытывают проблемы в данной области.\nПиковая масть предоставляет человеку возможность полностью раскрыть весь заложенный в нем потенциал. Но для этого необходимо смирить собственную волю, отвлекаться на время от работы, чтобы обнаружить и осознать свою тягу к духовности. В этом случае Пика может достичь высочайшей степени духовного развития, что принесет пользу и ей самой, и окружающим ее людям.", "Крести": "Люди-крести пришли в этот мир за знаниями. Они не умеют торговать картошкой или бананами и вряд ли этому когда-нибудь научатся, но вот продавать свои знания они должны уметь. ♣ Трефы ♣\nТрефы — масть знаний и идей, — школьные и студенческие годы, лето. Элемент — Воздух, масть Мечей в Таро.\nБольшинство людей, родившихся под управлением масти Треф, рациональны, умны, вдумчивы и любознательны. Внимательно прислушиваясь к своему внутреннему голосу, они имеют возможность развить интуицию и уникальные природные таланты. Сообразительные, с энтузиазмом относящиеся к интересующим их проблемам, они преуспеют, осознав, что главное их оружие — сила ума. Эти люди легко усваивают знания, красноречиво выражают свои мысли и с удовольствием участвуют в дебатах и дискуссиях. Их привлекают идеи, методы общения, качество их собственных мыслей и воззрений, а также возможность оставить в мире свой след, благодаря этим мыслям и воззрениям.\nТрефы судят людей по их словам и воспринимают слова всерьез. Рано или поздно большинство представителей Трефовой масти сталкиваются с серьезной проблемой: как отличить то, что люди говорят, от того, чем они на самом деле являются? Другая особенность Треф состоит в том, что они зачастую судят о ситуации, не принимая в расчет чувства ее участников. При этом нередко они забывают и о своих собственных эмоциях, которые могут являться истинной причиной сложившейся ситуации. Иногда Трефы могут злоупотреблять фактами и истиной. Например, они способны использовать информацию, которую вы нерасчетливо им доверили, против вас.\nТрефы, как правило, стремятся выяснить все детали и подробности интересующей их ситуации. Об этой особенности не следует забывать, если вы решили вступить в брак с представителем масти Треф. Такой человек станет расспрашивать вас обо всех мельчайших подробностях вашей жизни — не из-за того, что не доверяет вам, а просто потому, что это — одна из его главных потребностей.\nМногие Трефы сталкиваются в своей жизни с проблемами, имеющими отношение к свободе и независимости личности. Как ветер, символизирующий их стихию — Воздух, они могут появляться и исчезать, когда им заблагорассудится. Эта особенность зачастую мешает Трефам создавать устойчивые и длительные личные отношения. Представители масти Треф слишком сильно ассоциируют себя со своими подвижными, изменчивыми убеждениями, что может послужить препятствием на пути к счастливому браку. Конечно, это характерно не для всех представителей этой масти, но встречается среди них достаточно часто.", "Черви": "Люди-червы должны в этом воплощении научиться любить и быть любимыми. Их тоже меньше, чем крестовых и бубновых людей, правда, больше, чем людей-пик. Но что делать, сейчас такой век – век денег и знаний! И это ни плохо, ни хорошо, ведь у каждого из нас есть свои задачи, которые решать необходимо, и подчас это сделать нелегко. Так что давайте жить и работать с тем, что у нас есть, не завидуя другим – им ведь тоже приходится непросто, даже если мы этого и не замечаем. Червы — масть любви, романтики, любовных отношений и художественного самовыражения, — детство, весна. Элемент — Вода, масть Кубков в Таро.\nЛюди, родившиеся под управлением этой масти, впечатлительны и очень эмоциональны. Они улучшают свою жизнь, благодаря умению дарить любовь и оказывать поддержку, проявляя понимание и сострадание. Внимательные и чувственные, они часто становятся преданными друзьями и любящими партнерами. Женщины-Червы могут быть идеальными романтическими возлюбленными и женами.\nКак правило, человек, связанный с мастью Червей, в определенный момент времени концентрирует все свое внимание на ребенке, который становится для него смыслом жизни, либо же на романтическом партнере. Через некоторое время это навязчивое состояние прекращается, и человек находит равновесие между своей личностью и окружающим миром. Глубоко погружаясь в сферы, связанные с его мастью, он получает возможность лучше понять себя и свою внутреннюю сущность. Многие Червы всю жизнь посвящают себя художественному самовыражению, — среди представителей этой масти много известных актеров, музыкантов и художников.\nЛюди Червовой масти склонны чрезмерно опекать своих детей, угнетая и подавляя их, выражая свою любовь нездоровым способом. Червы имеют особое отношение к вопросам самооценки. Главными их орудиями являются одобрение и признание, либо их отсутствие. Представитель этой масти способен наделять людей признанием их уникальности и исключительности так же, как родители наделяют этим качеством своих детей. Когда же Черва желает причинить кому-то боль или установить над нами контроль, он лишает его этого признания. Это схемы поведения, которых чаще всего придерживаются Червы.\nЛюди, принадлежащие к масти Червей, должны учиться направлять свои эмоции, не поддаваться импульсивности и страхам, которые могут пробудить такие отрицательные качества, как эгоизм, ненависть или ревность."};
const JOKER = { card: "Joker", text: "Джокер" };

// Код даты (карта) по формуле 55 − (2 × месяц + день): 1 января = 52 (K♠), 30 декабря = 1 (A♥), 31 декабря = 0 (Джокер)
function dateCode(day, month) {
  return 55 - (2 * month + day);
}
function cardByCode(code) {
  return code === 0 ? JOKER : LOVE_CARDS[code];
}

function getBirthCardIndex(day, month) {
  return dateCode(day, month);
}

function getBirthCard(day, month) {
  const idx = getBirthCardIndex(day, month);
  const suit = BIRTH_CARD_SUIT[idx] || "";
  return {
    index: idx,
    card: cardByCode(idx).card,
    text: BIRTH_CARD_TEXTS[idx] || "",
    suit: suit,
    suitText: SUIT_TEXTS[suit] || "",
  };
}

// Персональная энергия каждого дня выбранного года: карта рождения + код даты, больше 52 — минус 52
function getYearForecast(day, month, year, targetYear) {
  const birthIdx = getBirthCardIndex(day, month);
  const rows = [];
  const start = Date.UTC(targetYear, 0, 1);
  const isLeap = (targetYear % 4 === 0 && targetYear % 100 !== 0) || targetYear % 400 === 0;
  const totalDays = isLeap ? 366 : 365;

  for (let i = 0; i < totalDays; i++) {
    const d = new Date(start + i * 86400000);
    let personalCode = birthIdx + dateCode(d.getUTCDate(), d.getUTCMonth() + 1);
    if (personalCode > 52) personalCode -= 52;
    const entry = cardByCode(personalCode);
    rows.push({
      date: String(d.getUTCDate()).padStart(2, "0") + "." + String(d.getUTCMonth() + 1).padStart(2, "0") + "." + targetYear,
      code: personalCode,
      card: entry.card,
      text: entry.text,
    });
  }
  return rows;
}

function getFullResult(day, month, year, name, targetYear) {
  const sy = targetYear || new Date().getFullYear();
  return {
    birthCard: getBirthCard(day, month),
    year: getYearForecast(day, month, year, sy),
  };
}

window.LoveCardsEngine = { getFullResult, getBirthCard, getYearForecast, getBirthCardIndex, dateCode };
